<div class="eng-print">
	<div class="header">
		{% if settings.company_logo %}
		<div class="header-logo">
			<img src="{{ settings.company_logo }}" alt="Logo">
		</div>
		{% endif %}
		<div class="header-info">
			<h1>{{ settings.company_name or "Escritório de Engenharia" }}</h1>
			{% if settings.company_crea %}
			<div class="muted">CREA {{ settings.company_crea }}</div>
			{% endif %}
		</div>
		<div class="header-meta">
			<div><strong>Obra:</strong> {{ doc.name }}</div>
			<div><strong>Emissão:</strong> {{ frappe.utils.formatdate(frappe.utils.today()) }}</div>
			{% if doc.status %}
			<div><strong>Status:</strong> {{ doc.status }}</div>
			{% endif %}
		</div>
	</div>

	<div class="doc-title">
		<h1>Orçamento da Obra</h1>
		<div class="muted">{{ doc.title or doc.name }}</div>
	</div>

	<h2>Dados da Obra</h2>
	<div class="grid">
		<div class="grid-row">
			<div class="grid-label">Cliente</div>
			<div class="grid-value"><strong>{{ customer_name }}</strong></div>
		</div>
		{% if doc.project_type %}
		<div class="grid-row">
			<div class="grid-label">Tipo de obra</div>
			<div class="grid-value">{{ doc.project_type }}</div>
		</div>
		{% endif %}
		{% if doc.start_date or doc.expected_delivery %}
		<div class="grid-row">
			<div class="grid-label">Prazo</div>
			<div class="grid-value">
				{% if doc.start_date %}Início: {{ frappe.utils.formatdate(doc.start_date) }}{% endif %}
				{% if doc.expected_delivery %}{% if doc.start_date %} — {% endif %}Entrega prevista: {{ frappe.utils.formatdate(doc.expected_delivery) }}{% endif %}
			</div>
		</div>
		{% endif %}
		{% if doc.construction_area %}
		<div class="grid-row">
			<div class="grid-label">Área construída</div>
			<div class="grid-value">{{ doc.construction_area }} m²</div>
		</div>
		{% endif %}
	</div>

	{% if doc.address_street or doc.city %}
	<h2>Endereço da Obra</h2>
	<div class="grid">
		<div class="grid-row">
			<div class="grid-label">Local</div>
			<div class="grid-value">
				{% if doc.address_street %}{{ doc.address_street }}{% if doc.address_number %}, {{ doc.address_number }}{% endif %}{% endif %}
				{% if doc.address_district %}<br>{{ doc.address_district }}{% endif %}
				{% if doc.city %}<br>{{ doc.city }}{% if doc.address_uf %} — {{ doc.address_uf }}{% endif %}{% endif %}
				{% if doc.address_cep %}<br>CEP: {{ doc.address_cep }}{% endif %}
			</div>
		</div>
		{% if doc.gps_coordinates %}
		<div class="grid-row">
			<div class="grid-label">Coordenadas GPS</div>
			<div class="grid-value">{{ doc.gps_coordinates }}</div>
		</div>
		{% endif %}
		{% if doc.property_registration %}
		<div class="grid-row">
			<div class="grid-label">Matrícula</div>
			<div class="grid-value">{{ doc.property_registration }}</div>
		</div>
		{% endif %}
	</div>
	{% endif %}

	{% if doc.responsible_engineer or doc.crea_number or doc.art_number %}
	<h2>Responsabilidade Técnica</h2>
	<div class="grid">
		{% if doc.responsible_engineer %}
		<div class="grid-row">
			<div class="grid-label">Responsável técnico</div>
			<div class="grid-value">{{ doc.responsible_engineer }}</div>
		</div>
		{% endif %}
		{% if doc.crea_number %}
		<div class="grid-row">
			<div class="grid-label">CREA</div>
			<div class="grid-value">{{ doc.crea_number }}</div>
		</div>
		{% endif %}
		{% if doc.art_number %}
		<div class="grid-row">
			<div class="grid-label">ART principal</div>
			<div class="grid-value">{{ doc.art_number }}</div>
		</div>
		{% endif %}
	</div>
	{% endif %}

	{% if project_items %}
	<h2>Itens do Projeto</h2>
	<table class="data">
		<thead>
			<tr>
				<th style="width: 5%;">#</th>
				<th>Item técnico</th>
				<th>Identificação</th>
				<th class="text-right">Qtd.</th>
				<th class="text-right">Valor total</th>
			</tr>
		</thead>
		<tbody>
			{% for item in project_items %}
			<tr>
				<td>{{ loop.index }}</td>
				<td>{{ item.technical_item }}</td>
				<td>{{ item.instance_label or item.title or "—" }}</td>
				<td class="text-right">{{ item.quantity or 1 }}</td>
				<td class="text-right">{{ frappe.utils.fmt_money(item.total_value) if item.total_value else "—" }}</td>
			</tr>
			{% endfor %}
		</tbody>
	</table>
	{% endif %}

	{% if doc.spec_project_total %}
	<div class="total-box">
		<div class="total-label">Total das especificações</div>
		<div class="total-value">{{ doc.get_formatted("spec_project_total") }}</div>
	</div>
	{% endif %}

	{% if doc.current_contract_value %}
	<div class="grid" style="margin-top: 16px;">
		<div class="grid-row">
			<div class="grid-label">Valor atual do contrato</div>
			<div class="grid-value"><strong>{{ doc.get_formatted("current_contract_value") }}</strong></div>
		</div>
	</div>
	{% endif %}

	{% if doc.observations %}
	<h2>Observações</h2>
	<div class="muted">{{ doc.observations }}</div>
	{% endif %}
</div>
